public void connect(Context context, String str, Integer num, ReadableMap readableMap, Network network, ReadableMap readableMap2) throws GeneralSecurityException, IOException {
    if (this.socket != null) {
        throw new IOException("Already connected");
    }
    if (readableMap2 != null) {
        Socket socketCreateSocket = getSSLSocketFactory(context, readableMap2).createSocket();
        this.socket = socketCreateSocket;
        ((SSLSocket) socketCreateSocket).setUseClientMode(true);
    } else {
        this.socket = new Socket();
    }
    InetAddress byName = InetAddress.getByName(readableMap.hasKey("localAddress") ? readableMap.getString("localAddress") : "0.0.0.0");
    InetAddress byName2 = InetAddress.getByName(str);
    if (network != null) {
        network.bindSocket(this.socket);
    }
    if (readableMap.hasKey("reuseAddress")) {
        this.socket.setReuseAddress(readableMap.getBoolean("reuseAddress"));
    } else {
        this.socket.setReuseAddress(true);
    }
