    this.socket.connect(new InetSocketAddress(byName2, num.intValue()), readableMap.hasKey("connectTimeout") ? readableMap.getInt("connectTimeout") : 0);
    Socket socket = this.socket;
    if (socket instanceof SSLSocket) {
        ((SSLSocket) socket).startHandshake();
    }
    startListening();
}
